#[derive(Clone, Copy)]
struct WotsTestVector<const N: usize, const LEN: usize> {
    layer: u32,
    tree: u64,
    address: u32,
    seed: [u8; N],
    private_key: [u8; N],
    message: [u8; N],
    signature: [[u8; N]; LEN],
    public_key: [u8; N],
}

const fn patterned_bytes<const N: usize>(multiplier: u8, addend: u8) -> [u8; N] {
    let mut result = [0; N];
    let mut i = 0;
    while i < result.len() {
        result[i] = (i as u8).wrapping_mul(multiplier).wrapping_add(addend);
        i += 1;
    }
    result
}

const fn decode_hex_nibble(value: u8) -> u8 {
    match value {
        b'0'..=b'9' => value - b'0',
        b'a'..=b'f' => value - b'a' + 10,
        _ => panic!("invalid hexadecimal test-vector byte"),
    }
}

const fn bytes_from_hex<const N: usize>(value: &str) -> [u8; N] {
    let value = value.as_bytes();
    assert!(value.len() == N * 2);

    let mut result = [0; N];
    let mut i = 0;
    while i < N {
        result[i] = decode_hex_nibble(value[2 * i]) << 4 | decode_hex_nibble(value[2 * i + 1]);
        i += 1;
    }
    result
}

const fn signature_from_hex<const N: usize, const LEN: usize>(value: &str) -> [[u8; N]; LEN] {
    let value = value.as_bytes();
    assert!(value.len() == LEN * N * 2);

    let mut result = [[0; N]; LEN];
    let mut i = 0;
    while i < LEN {
        let mut j = 0;
        while j < N {
            let offset = 2 * (i * N + j);
            result[i][j] =
                decode_hex_nibble(value[offset]) << 4 | decode_hex_nibble(value[offset + 1]);
            j += 1;
        }
        i += 1;
    }
    result
}

