#[test]
fn sha256() {
    for vector in &SHA256 {
        let seed = Output::<Sha256>::from(vector.seed);
        let mut scheme = Sha256::from(&seed);
        scheme.layer = vector.layer;
        scheme.tree = vector.tree;
        scheme.address = vector.address;
        test_vector(scheme, vector);
    }
}

